INSERT INTO `accommodation_room_types` VALUES (1,1,'Honeymoon Ocean Suite','A romantic suite steps from the sea, with a private plunge pool and daily rose-petal turndown.',850000.00,'TZS',2,'1 King',65,'[\"Private plunge pool\",\"Ocean view\",\"Outdoor rain shower\",\"Butler service\"]','https://images.unsplash.com/photo-1590490360182-c33d57733427?w=900&q=80',4,1,'2026-08-01 18:38:44','2026-08-01 18:38:44'),(2,1,'Deluxe Garden Room','A serene room overlooking the tropical gardens.',420000.00,'TZS',2,'1 Queen',38,'[\"Garden view\",\"Balcony\",\"Minibar\"]','https://images.unsplash.com/photo-1611892440504-42a792e24d32?w=900&q=80',12,1,'2026-08-01 18:38:44','2026-08-01 18:38:44'),(3,1,'Beachfront Villa','A spacious villa on the sand for a small wedding party or family.',1450000.00,'TZS',4,'2 King',120,'[\"Private beach access\",\"Two bedrooms\",\"Full kitchen\",\"Private pool\"]','https://images.unsplash.com/photo-1582719508461-905c673771fd?w=900&q=80',2,1,'2026-08-01 18:38:44','2026-08-01 18:38:44'),(4,2,'Honeymoon Tented Suite','A canvas suite with an open-air bath and uninterrupted views of the migration.',1200000.00,'TZS',2,'1 King',55,'[\"Private deck\",\"Plains view\",\"Outdoor bath\",\"Personal butler\"]','https://images.unsplash.com/photo-1504280390367-361c6d9f38f4?w=900&q=80',3,1,'2026-08-01 18:38:44','2026-08-01 18:38:44'),(5,2,'Classic Safari Tent','A comfortable tent with all the essentials for a bush adventure.',780000.00,'TZS',2,'1 Queen',40,'[\"En-suite bathroom\",\"Private deck\",\"Lantern lighting\"]','https://images.unsplash.com/photo-1445019980597-93fa8acb246c?w=900&q=80',8,1,'2026-08-01 18:38:44','2026-08-01 18:38:44'),(6,3,'Executive Suite','A refined suite with skyline views and executive-lounge access.',360000.00,'TZS',2,'1 King',45,'[\"Harbour view\",\"Lounge access\",\"Nespresso\"]','https://images.unsplash.com/photo-1631049307264-da0ec9d70304?w=900&q=80',6,1,'2026-08-01 18:38:44','2026-08-01 18:38:44'),(7,3,'Standard Double','A smart, comfortable room for guests in town for the celebration.',180000.00,'TZS',2,'1 Double',28,'[\"City view\",\"Work desk\"]','https://images.unsplash.com/photo-1595576508898-0ad5c879a061?w=900&q=80',20,1,'2026-08-01 18:38:44','2026-08-01 18:38:44');
