INSERT INTO `accommodations` VALUES (1,NULL,'Zanzibar Pearl Beach Resort & Spa','zanzibar-pearl-beach-resort-spa','A five-star beachfront sanctuary on the white sands of Nungwi — the classic Tanzanian honeymoon escape, with private plunge pools, a spa and sunset dhow cruises.',5,'Zanzibar','Nungwi, Zanzibar',NULL,'[\"Private beach\",\"Infinity pool\",\"Spa & wellness\",\"Free Wi-Fi\",\"Airport transfer\",\"Breakfast included\",\"Sunset cruises\"]','https://images.unsplash.com/photo-1520250497591-112f2f40a3f4?w=1200&q=80',NULL,'TZS',420000.00,'14:00','11:00','Free cancellation up to 14 days before check-in. Honeymoon package includes a complimentary candlelit dinner.','+255 24 555 0100','reservations@zanzibarpearl.example',1,1,2,'2026-08-01 18:38:44','2026-08-01 18:46:37'),(2,NULL,'Serengeti Sky Luxury Lodge','serengeti-sky-luxury-lodge','A luxury tented lodge overlooking the endless plains — game drives at dawn, champagne at dusk. An unforgettable safari honeymoon.',5,'Serengeti','Central Serengeti, Tanzania',NULL,'[\"Game drives\",\"All-inclusive dining\",\"Infinity pool\",\"Spa\",\"Wi-Fi in lounge\",\"Bush dinners\"]','https://images.unsplash.com/photo-1516426122078-c23e76319801?w=1200&q=80',NULL,'TZS',780000.00,'13:00','10:00','Rates are full-board and include two game drives daily. Cancellation up to 30 days before arrival.','+255 28 555 0180','stay@serengetisky.example',1,1,0,'2026-08-01 18:38:44','2026-08-01 18:38:44'),(3,NULL,'Dar Riverside City Hotel','dar-riverside-city-hotel','A stylish four-star city hotel by the harbour — ideal for a pre-honeymoon night or out-of-town wedding guests.',4,'Dar es Salaam','Masaki, Dar es Salaam',NULL,'[\"Rooftop pool\",\"Gym\",\"Free Wi-Fi\",\"Restaurant\",\"Airport shuttle\",\"Business centre\"]','https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1200&q=80',NULL,'TZS',180000.00,'14:00','12:00','Free cancellation up to 48 hours before arrival.','+255 22 555 0140','book@darriverside.example',0,1,0,'2026-08-01 18:38:44','2026-08-01 18:38:44');
