INSERT INTO `ai_knowledge_documents` VALUES (1,1,NULL,'Preferred catering vendors','Vendor notes','For weddings we prefer Zawadi Catering (reliable, great buffet) and Bella Foods for plated dinners. Always confirm a tasting 6 weeks before the event and negotiate a 10% deposit.',0,'manual','2026-07-27 12:34:46','2026-07-27 12:34:46');
