INSERT INTO `ai_templates` VALUES (1,NULL,'client_proposal','proposal','Client Event Proposal','A polished proposal for a client — scope, plan, budget summary and next steps, drawn from the event.','FileText','markdown',NULL,'[{\"key\":\"client_name\",\"label\":\"Client name\",\"type\":\"text\",\"required\":false,\"placeholder\":\"e.g. The Bennett family\"},{\"key\":\"company\",\"label\":\"Your company \\/ signature\",\"type\":\"text\",\"required\":false,\"placeholder\":\"e.g. OSEP Events\"}]',1,1,10,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(2,NULL,'planning_timeline','timeline','Planning Timeline','A countdown planning schedule to the event date — grounded in your milestones, or a best-practice plan if none exist yet.','CalendarClock','markdown',NULL,'[]',1,1,20,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(3,NULL,'run_of_show','checklist','Run of Show (Day-Of Schedule)','A minute-by-minute day-of schedule and coordination checklist for the event.','ListChecks','markdown',NULL,'[{\"key\":\"start_time\",\"label\":\"Guest arrival time\",\"type\":\"text\",\"required\":false,\"placeholder\":\"e.g. 4:00 PM\"}]',1,1,30,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(4,NULL,'vendor_brief','vendor','Vendor Brief / RFQ','A brief to send a vendor requesting a quote — event details, requirements and what to include.','Store','markdown',NULL,'[{\"key\":\"service_needed\",\"label\":\"Service needed\",\"type\":\"text\",\"required\":true,\"placeholder\":\"e.g. Catering for 120 guests\"}]',1,1,40,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(5,NULL,'rsvp_reminder_email','email','RSVP Reminder Email','A warm reminder email to guests who have not yet responded, referencing real RSVP numbers and the deadline.','Mail','markdown',NULL,'[{\"key\":\"reply_by\",\"label\":\"Reply-by date\",\"type\":\"text\",\"required\":false,\"placeholder\":\"e.g. two weeks before\"}]',1,1,50,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(6,NULL,'client_update_email','email','Client Status Update Email','A concise progress update to the client — where the event stands across budget, tasks, guests and vendors.','MailCheck','markdown',NULL,'[{\"key\":\"client_name\",\"label\":\"Client name\",\"type\":\"text\",\"required\":false,\"placeholder\":\"e.g. Sarah\"}]',1,1,60,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(7,NULL,'budget_outline','budget','Budget Breakdown Guide','A recommended budget allocation for the event — measured against your real figures where a budget exists.','Wallet','markdown',NULL,'[{\"key\":\"event_type\",\"label\":\"Event type\",\"type\":\"text\",\"required\":false,\"placeholder\":\"e.g. Wedding\"},{\"key\":\"total_budget\",\"label\":\"Total budget (TZS)\",\"type\":\"number\",\"required\":false,\"placeholder\":\"e.g. 20000000\"}]',0,1,70,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(8,NULL,'welcome_speech','speech','Welcome Speech / Toast','A heartfelt welcome speech or toast, personalised to the occasion and the event.','Sparkles','markdown',NULL,'[{\"key\":\"occasion\",\"label\":\"Occasion\",\"type\":\"text\",\"required\":true,\"placeholder\":\"e.g. 50th birthday celebration\"},{\"key\":\"speaker_name\",\"label\":\"Speaker name\",\"type\":\"text\",\"required\":false,\"placeholder\":\"e.g. James\"},{\"key\":\"tone\",\"label\":\"Tone\",\"type\":\"select\",\"required\":false,\"options\":[\"Warm\",\"Formal\",\"Light-hearted\"],\"placeholder\":\"Warm\"}]',0,1,80,'2026-07-27 11:37:01','2026-07-27 11:37:01'),(9,NULL,'social_announcement','social','Social Media Announcement','Ready-to-post announcement copy with hashtags to build anticipation for the event.','Sparkle','markdown',NULL,'[{\"key\":\"platform\",\"label\":\"Platform\",\"type\":\"select\",\"required\":false,\"options\":[\"Instagram\",\"Facebook\",\"LinkedIn\",\"X \\/ Twitter\"],\"placeholder\":\"Instagram\"},{\"key\":\"headline\",\"label\":\"What are you announcing?\",\"type\":\"text\",\"required\":true,\"placeholder\":\"e.g. Save the date\"}]',0,1,90,'2026-07-27 11:37:01','2026-07-27 11:37:01');
/*!40000 ALTER TABLE `ai_templates` ENABLE KEYS */;
