  CONSTRAINT `booking_requests_planner_id_foreign` FOREIGN KEY (`planner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `booking_requests_vendor_id_foreign` FOREIGN KEY (`vendor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `booking_requests_venue_id_foreign` FOREIGN KEY (`venue_id`) REFERENCES `marketplace_venues` (`id`) ON DELETE SET NULL
