INSERT INTO `invitation_templates` VALUES (1,NULL,'Classic Wedding','wedding','You\'re invited to our wedding','Dear {{first_name}},\n\nTogether with our families, we joyfully invite you to celebrate our wedding. Your presence would mean the world to us.\n\nWith love.',NULL,NULL,'{\"primary\":\"#b45309\",\"accent\":\"#fcd34d\",\"font\":\"serif\"}',NULL,1,'2026-07-26 13:59:23','2026-07-26 13:59:23'),(2,NULL,'Birthday Bash','birthday','Let\'s celebrate!','Hi {{first_name}},\n\nYou\'re invited to a birthday celebration full of fun, food and good company. Come ready to party!',NULL,NULL,'{\"primary\":\"#be123c\",\"accent\":\"#fda4af\",\"font\":\"sans\"}',NULL,1,'2026-07-26 13:59:23','2026-07-26 13:59:23'),(3,NULL,'Conference Invite','conference','Your invitation to {{event}}','Hello {{first_name}},\n\nWe\'re pleased to invite you to {{event}}. Join industry leaders for a day of insight and networking.',NULL,NULL,'{\"primary\":\"#1e3a8a\",\"accent\":\"#93c5fd\",\"font\":\"sans\"}',NULL,1,'2026-07-26 13:59:23','2026-07-26 13:59:23'),(4,NULL,'Corporate Event','corporate','You are invited — {{event}}','Dear {{first_name}},\n\nWe would be honoured to have you join us at {{event}}. Kindly let us know if you can attend.',NULL,NULL,'{\"primary\":\"#0f766e\",\"accent\":\"#5eead4\",\"font\":\"sans\"}',NULL,1,'2026-07-26 13:59:23','2026-07-26 13:59:23'),(5,NULL,'Graduation','graduation','Come celebrate our graduate','Hi {{first_name}},\n\nWe\'re proud to invite you to celebrate this milestone. Your support has meant so much on this journey.',NULL,NULL,'{\"primary\":\"#7c3aed\",\"accent\":\"#c4b5fd\",\"font\":\"serif\"}',NULL,1,'2026-07-26 13:59:23','2026-07-26 13:59:23');
