INSERT INTO `notifications` VALUES (1,1,'client_request','New client enquiry','Amina Hassan requested a proposal for a corporate gala.','{\"event_id\":1}','2026-07-27 05:07:55','2026-07-26 13:59:29','2026-07-27 05:07:55'),(2,1,'vendor_quotation','Vendor quotation received','Zawadi Photography submitted a quote for the wedding.','{\"event_id\":1}','2026-07-27 05:07:55','2026-07-26 13:59:29','2026-07-27 05:07:55'),(3,1,'approval_completed','Catering approved','John Carter approved the catering quotation for Sarah & John\'s Wedding.','{\"event_id\":1}','2026-07-27 05:07:55','2026-07-26 13:59:29','2026-07-27 05:07:55'),(4,2,'proposal','Proposal ready for review','Your decoration proposal is ready — please review and approve.','{\"event_id\":1}','2026-07-30 15:37:40','2026-07-26 13:59:29','2026-07-30 15:37:40'),(5,2,'payment_reminder','Payment reminder','A deposit of TZS 5,000,000 is due on 30 July 2026.','{\"event_id\":1}','2026-07-30 15:37:40','2026-07-26 13:59:29','2026-07-30 15:37:40'),(6,2,'planning_update','Planning update','Catering has been confirmed. You are now 65% complete.','{\"event_id\":1}','2026-07-30 15:37:40','2026-07-26 13:59:29','2026-07-30 15:37:40'),(7,1,'contract_active','Contract Active','Contract CON-2026-ZAWADI is now Active.','{\"contract_id\":1}','2026-07-27 05:07:55','2026-07-26 14:33:11','2026-07-27 05:07:55'),(8,20,'event_update','You have a new event','Sarah Bennett added you to \"pree\".','{\"event_id\":4}',NULL,'2026-07-26 19:04:16','2026-07-26 19:04:16'),(9,20,'event_update','You have a new event','Sarah Bennett added you to \"kee\".','{\"event_id\":6}',NULL,'2026-07-26 19:28:34','2026-07-26 19:28:34'),(10,1,'new_booking_request','New booking request','John Carter wants to book your services.','{\"request_id\":1}','2026-07-27 05:07:55','2026-07-27 04:07:30','2026-07-27 05:07:55'),(11,2,'booking_accepted','Booking accepted!','Sarah Bennett accepted your request. Your event is ready.','{\"request_id\":1,\"event_id\":7}','2026-07-30 15:37:40','2026-07-27 04:17:36','2026-07-30 15:37:40'),(12,1,'new_booking_request','New booking request','John Carter wants to book your services.','{\"request_id\":2}','2026-07-27 05:07:55','2026-07-27 04:29:37','2026-07-27 05:07:55'),(14,2,'booking_declined','Booking request declined','Sarah Bennett was unable to take your request.','{\"request_id\":2}','2026-07-30 15:37:40','2026-07-27 05:07:43','2026-07-30 15:37:40'),(15,19,'message','New message','Sarah Bennett sent you a message.','{\"conversation_id\":1}',NULL,'2026-07-27 06:46:43','2026-07-27 06:46:43'),(16,2,'event_update','You have a new event','Sarah Bennett added you to \"rrr\".','{\"event_id\":8}','2026-07-30 15:37:40','2026-07-28 07:35:41','2026-07-30 15:37:40'),(18,6,'quotation_negotiate','Quotation wants to negotiate','A planner wants to negotiate your quotation QUO-2026-NEEMA.','{\"quotation_id\":2}',NULL,'2026-07-28 16:49:45','2026-07-28 16:49:45'),(19,6,'quotation_negotiate','Quotation wants to negotiate','A planner wants to negotiate your quotation QUO-2026-NEEMA.','{\"quotation_id\":2}',NULL,'2026-07-28 16:49:49','2026-07-28 16:49:49'),(20,2,'booking_declined','Booking request declined','Sarah Bennett was unable to take your request.','{\"request_id\":3}','2026-07-30 15:37:40','2026-07-28 17:00:42','2026-07-30 15:37:40'),(24,1,'rsvp_received','RSVP received','Grace Mwakalinga responded \"Attending\" for Sarah & John\'s Wedding.','{\"event_id\":1,\"guest_id\":1}',NULL,'2026-08-12 15:34:10','2026-08-12 15:34:10');
