  CONSTRAINT `planner_booking_requests_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE SET NULL,
  CONSTRAINT `planner_booking_requests_planner_id_foreign` FOREIGN KEY (`planner_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
