  PRIMARY KEY (`id`),
  UNIQUE KEY `qr_codes_guest_id_unique` (`guest_id`),
  UNIQUE KEY `qr_codes_token_unique` (`token`),
  KEY `qr_codes_event_id_foreign` (`event_id`),
  CONSTRAINT `qr_codes_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `qr_codes_guest_id_foreign` FOREIGN KEY (`guest_id`) REFERENCES `guests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
