DROP TABLE IF EXISTS `reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reviews` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reviewer_id` bigint(20) unsigned NOT NULL,
  `vendor_id` bigint(20) unsigned DEFAULT NULL,
  `venue_id` bigint(20) unsigned DEFAULT NULL,
  `event_id` bigint(20) unsigned DEFAULT NULL,
  `contract_id` bigint(20) unsigned DEFAULT NULL,
  `rating_professionalism` tinyint(3) unsigned DEFAULT NULL,
  `rating_communication` tinyint(3) unsigned DEFAULT NULL,
  `rating_quality` tinyint(3) unsigned DEFAULT NULL,
  `rating_value` tinyint(3) unsigned DEFAULT NULL,
  `rating_timeliness` tinyint(3) unsigned DEFAULT NULL,
  `overall_rating` decimal(3,2) NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `comment` text DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'published',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `reviews_reviewer_id_foreign` (`reviewer_id`),
  KEY `reviews_event_id_foreign` (`event_id`),
  KEY `reviews_contract_id_foreign` (`contract_id`),
  KEY `reviews_vendor_id_status_index` (`vendor_id`,`status`),
  KEY `reviews_venue_id_status_index` (`venue_id`,`status`),
  KEY `reviews_status_index` (`status`),
  CONSTRAINT `reviews_contract_id_foreign` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reviews_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reviews_reviewer_id_foreign` FOREIGN KEY (`reviewer_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `reviews_vendor_id_foreign` FOREIGN KEY (`vendor_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `reviews_venue_id_foreign` FOREIGN KEY (`venue_id`) REFERENCES `marketplace_venues` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

