DROP TABLE IF EXISTS `vendor_profiles`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `vendor_profiles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `business_name` varchar(255) DEFAULT NULL,
  `tagline` varchar(255) DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `description` text DEFAULT NULL,
  `years_in_business` int(10) unsigned DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `contact_email` varchar(255) DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `social_links` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`social_links`)),
  `logo_url` varchar(255) DEFAULT NULL,
  `cover_image_url` varchar(255) DEFAULT NULL,
  `verification_status` varchar(255) NOT NULL DEFAULT 'pending',
  `verification_level` varchar(255) NOT NULL DEFAULT 'unverified',
  `availability_status` varchar(255) NOT NULL DEFAULT 'available',
  `profile_views` int(10) unsigned NOT NULL DEFAULT 0,
  `pending_requests` int(10) unsigned NOT NULL DEFAULT 0,
  `response_time_hours` int(10) unsigned DEFAULT NULL,
  `completed_jobs` int(10) unsigned NOT NULL DEFAULT 0,
  `reviews_count` int(10) unsigned NOT NULL DEFAULT 0,
  `rating` decimal(3,2) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `is_suspended` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vendor_profiles_user_id_unique` (`user_id`),
  KEY `vendor_profiles_verification_status_index` (`verification_status`),
  KEY `vendor_profiles_availability_status_index` (`availability_status`),
  KEY `vendor_profiles_category_id_foreign` (`category_id`),
  KEY `vendor_profiles_verification_level_index` (`verification_level`),
  KEY `vendor_profiles_is_featured_index` (`is_featured`),
  KEY `vendor_profiles_is_suspended_index` (`is_suspended`),
  CONSTRAINT `vendor_profiles_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `vendor_categories` (`id`) ON DELETE SET NULL,
  CONSTRAINT `vendor_profiles_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=186 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

